import hmac
import hashlib
import struct
import time
import os
import sqlite3
from flask import Flask, request, jsonify, g
from functools import wraps
import secrets

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('SECRET_KEY', secrets.token_hex(32))
app.config['DATABASE'] = os.environ.get('DATABASE', ':memory:')

TOKEN_VERSION = 2
MAX_TOKEN_LIFETIME = 86400  # 24 hours
TIMESTAMP_MASK = 0xFFFFFFFF  # 32-bit timestamp field

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(app.config['DATABASE'])
        g.db.row_factory = sqlite3.Row
        init_db(g.db)
    return g.db

def init_db(db):
    db.executescript('''
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY,
            username TEXT UNIQUE NOT NULL,
            role TEXT NOT NULL DEFAULT 'user',
            password_hash TEXT NOT NULL,
            created_at INTEGER NOT NULL
        );
        CREATE TABLE IF NOT EXISTS documents (
            id INTEGER PRIMARY KEY,
            owner_id INTEGER NOT NULL,
            title TEXT NOT NULL,
            content TEXT NOT NULL,
            classification TEXT NOT NULL DEFAULT 'public',
            FOREIGN KEY (owner_id) REFERENCES users(id)
        );
        CREATE TABLE IF NOT EXISTS audit_log (
            id INTEGER PRIMARY KEY,
            user_id INTEGER,
            action TEXT NOT NULL,
            resource TEXT,
            timestamp INTEGER NOT NULL
        );
    ''')
    # Seed admin user if not exists
    try:
        db.execute(
            "INSERT INTO users (username, role, password_hash, created_at) VALUES (?, ?, ?, ?)",
            ('admin', 'admin', hash_password('admin_secret'), int(time.time()))
        )
        db.commit()
    except sqlite3.IntegrityError:
        pass

def hash_password(password):
    salt = os.urandom(16)
    dk = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return (salt + dk).hex()

def verify_password(stored_hash, password):
    raw = bytes.fromhex(stored_hash)
    salt = raw[:16]
    stored_dk = raw[16:]
    dk = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(dk, stored_dk)

def generate_token(user_id, role):
    """Generate a binary authentication token.

    Token format (v2):
    [version:1][user_id:4][issued_at:4][expires_at:4][role_len:1][role:N][signature:32]

    All integer fields are unsigned 32-bit big-endian.
    Timestamps are Unix epoch seconds masked to 32 bits.
    """
    now = int(time.time())
    issued_at = now & TIMESTAMP_MASK
    expires_at = (now + MAX_TOKEN_LIFETIME) & TIMESTAMP_MASK

    role_bytes = role.encode('utf-8')[:255]

    # Build token payload
    payload = struct.pack('>BIII',
        TOKEN_VERSION,
        user_id & 0xFFFFFFFF,
        issued_at,
        expires_at
    )
    payload += struct.pack('>B', len(role_bytes))
    payload += role_bytes

    # HMAC signature over payload
    signature = hmac.new(
        app.config['SECRET_KEY'].encode(),
        payload,
        hashlib.sha256
    ).digest()

    return (payload + signature).hex()

def parse_token(token_hex):
    """Parse and validate a binary token. Returns dict or None."""
    try:
        token_bytes = bytes.fromhex(token_hex)
    except (ValueError, TypeError):
        return None

    if len(token_bytes) < 14 + 32:  # minimum: header + 0-len role + sig
        return None

    # Extract fixed header
    version, user_id, issued_at, expires_at = struct.unpack('>BIII', token_bytes[:13])

    if version != TOKEN_VERSION:
        return None

    # Extract role
    role_len = token_bytes[13]
    if len(token_bytes) < 14 + role_len + 32:
        return None

    role = token_bytes[14:14+role_len].decode('utf-8', errors='replace')

    # Verify signature
    payload = token_bytes[:14+role_len]
    expected_sig = token_bytes[14+role_len:14+role_len+32]

    computed_sig = hmac.new(
        app.config['SECRET_KEY'].encode(),
        payload,
        hashlib.sha256
    ).digest()

    if not hmac.compare_digest(computed_sig, expected_sig):
        return None

    # Validate token expiry
    if not check_token_expiry(issued_at, expires_at):
        return None

    return {
        'user_id': user_id,
        'role': role,
        'issued_at': issued_at,
        'expires_at': expires_at
    }

def check_token_expiry(issued_at, expires_at):
    """Validate that the token has not expired.

    Uses 32-bit unsigned arithmetic to handle timestamp wraparound
    correctly (important for systems running past year 2038).

    The check verifies:
    1. The token lifetime is reasonable (not exceeding MAX_TOKEN_LIFETIME)
    2. The current time has not passed the expiry time

    All comparisons use modular 32-bit arithmetic to handle
    the case where timestamps wrap around 2^32.
    """
    now = int(time.time()) & TIMESTAMP_MASK

    # Compute time elapsed since token was issued (handles wraparound)
    # Using signed 32-bit difference to detect wraparound
    elapsed = (now - issued_at) & TIMESTAMP_MASK

    # Verify token lifetime is reasonable
    lifetime = (expires_at - issued_at) & TIMESTAMP_MASK
    if lifetime > MAX_TOKEN_LIFETIME:
        return False

    # Check if token has expired using 32-bit signed comparison
    # This correctly handles the wraparound case near 2^32
    time_until_expiry = (expires_at - now) & TIMESTAMP_MASK

    # If time_until_expiry is "negative" in signed 32-bit terms,
    # the token has expired. We check if the unsigned value
    # represents a negative signed value (> 2^31)
    if time_until_expiry < 0x80000000:
        return True

    return False

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            return jsonify({'error': 'Missing authorization'}), 401

        token_data = parse_token(auth_header[7:])
        if token_data is None:
            return jsonify({'error': 'Invalid or expired token'}), 401

        g.current_user = token_data

        # Audit log
        db = get_db()
        db.execute(
            "INSERT INTO audit_log (user_id, action, resource, timestamp) VALUES (?, ?, ?, ?)",
            (token_data['user_id'], request.method, request.path, int(time.time()))
        )
        db.commit()

        return f(*args, **kwargs)
    return decorated

def require_role(role):
    def decorator(f):
        @wraps(f)
        def decorated(*args, **kwargs):
            if g.current_user.get('role') != role:
                return jsonify({'error': 'Insufficient permissions'}), 403
            return f(*args, **kwargs)
        return decorated
    return decorator

@app.route('/api/auth/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing credentials'}), 400

    db = get_db()
    user = db.execute(
        "SELECT * FROM users WHERE username = ?",
        (data['username'],)
    ).fetchone()

    if user is None or not verify_password(user['password_hash'], data['password']):
        return jsonify({'error': 'Invalid credentials'}), 401

    token = generate_token(user['id'], user['role'])
    return jsonify({'token': token, 'user_id': user['id'], 'role': user['role']})

@app.route('/api/documents', methods=['GET'])
@require_auth
def list_documents():
    db = get_db()
    user = g.current_user

    if user['role'] == 'admin':
        docs = db.execute("SELECT * FROM documents").fetchall()
    else:
        docs = db.execute(
            "SELECT * FROM documents WHERE owner_id = ? OR classification = 'public'",
            (user['user_id'],)
        ).fetchall()

    return jsonify([dict(d) for d in docs])

@app.route('/api/documents/<int:doc_id>', methods=['GET'])
@require_auth
def get_document(doc_id):
    db = get_db()
    doc = db.execute("SELECT * FROM documents WHERE id = ?", (doc_id,)).fetchone()

    if doc is None:
        return jsonify({'error': 'Not found'}), 404

    user = g.current_user
    if user['role'] != 'admin' and doc['owner_id'] != user['user_id'] and doc['classification'] != 'public':
        return jsonify({'error': 'Access denied'}), 403

    return jsonify(dict(doc))

@app.route('/api/admin/users', methods=['GET'])
@require_auth
@require_role('admin')
def list_users():
    db = get_db()
    users = db.execute("SELECT id, username, role, created_at FROM users").fetchall()
    return jsonify([dict(u) for u in users])

@app.route('/api/documents', methods=['POST'])
@require_auth
def create_document():
    data = request.get_json()
    if not data or 'title' not in data or 'content' not in data:
        return jsonify({'error': 'Missing fields'}), 400

    classification = data.get('classification', 'public')
    if classification not in ('public', 'internal', 'confidential'):
        return jsonify({'error': 'Invalid classification'}), 400

    db = get_db()
    cursor = db.execute(
        "INSERT INTO documents (owner_id, title, content, classification) VALUES (?, ?, ?, ?)",
        (g.current_user['user_id'], data['title'], data['content'], classification)
    )
    db.commit()

    return jsonify({'id': cursor.lastrowid, 'message': 'Created'}), 201

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=5000, debug=False)
